CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS countries(code char(2) PRIMARY KEY,name text NOT NULL);
CREATE TABLE IF NOT EXISTS regions(id text PRIMARY KEY,country char(2) REFERENCES countries(code),name text NOT NULL);
CREATE TABLE IF NOT EXISTS categories(id text PRIMARY KEY,name text NOT NULL);
CREATE TABLE IF NOT EXISTS organizations(id text PRIMARY KEY,name text NOT NULL,government_affiliation text NOT NULL);
CREATE TABLE IF NOT EXISTS sources(id text PRIMARY KEY,url text NOT NULL UNIQUE,host text NOT NULL,organization_id text REFERENCES organizations(id),approved boolean NOT NULL DEFAULT false,last_checked timestamptz,last_hash text,robots_status text);
CREATE TABLE IF NOT EXISTS directory_state(singleton integer PRIMARY KEY CHECK(singleton=1),version bigint NOT NULL DEFAULT 1);
INSERT INTO directory_state(singleton) VALUES(1) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS directory_versions(version bigint PRIMARY KEY,published_at timestamptz NOT NULL DEFAULT now(),actor text NOT NULL,notes text NOT NULL);
CREATE TABLE IF NOT EXISTS helplines(id text PRIMARY KEY,country char(2) NOT NULL REFERENCES countries(code),source_id text NOT NULL REFERENCES sources(id),payload jsonb NOT NULL,revision integer NOT NULL DEFAULT 1,published boolean NOT NULL DEFAULT true,updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS helplines_country ON helplines(country) WHERE published=true;
CREATE TABLE IF NOT EXISTS channels(helpline_id text REFERENCES helplines(id) ON DELETE CASCADE,kind text CHECK(kind IN('phone','sms','whatsapp','email','web')),value text NOT NULL,immediate boolean NOT NULL DEFAULT false,PRIMARY KEY(helpline_id,kind,value));
CREATE TABLE IF NOT EXISTS helpline_history(id bigserial PRIMARY KEY,helpline_id text NOT NULL,payload jsonb NOT NULL,revision integer NOT NULL,actor text NOT NULL,changed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS verification_reviews(id text PRIMARY KEY,helpline_id text,source_id text REFERENCES sources(id),kind text NOT NULL CHECK(kind IN('record','source_change')),payload jsonb NOT NULL,base_revision integer NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','rejected')),proposer text NOT NULL,reviewer text,notes text,created_at timestamptz NOT NULL DEFAULT now(),reviewed_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS pending_source_change ON verification_reviews(source_id) WHERE kind='source_change' AND status='pending';
CREATE TABLE IF NOT EXISTS users(id text PRIMARY KEY,password_hash text,role text NOT NULL DEFAULT 'user' CHECK(role IN('user','reviewer','publisher')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS trusted_contacts(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),encrypted_payload bytea NOT NULL);
CREATE TABLE IF NOT EXISTS user_preferences(user_id text PRIMARY KEY REFERENCES users(id),payload jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS sos_sessions(id text PRIMARY KEY,capability_hash text NOT NULL,status text NOT NULL CHECK(status IN('active','safe','cancelled')),created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,country char(2) REFERENCES countries(code));
CREATE TABLE IF NOT EXISTS location_updates(id bigserial PRIMARY KEY,session_id text NOT NULL REFERENCES sos_sessions(id) ON DELETE CASCADE,lat double precision CHECK(lat BETWEEN -90 AND 90),lng double precision CHECK(lng BETWEEN -180 AND 180),accuracy double precision CHECK(accuracy>=0),recorded_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS locations_session ON location_updates(session_id,recorded_at DESC);
CREATE TABLE IF NOT EXISTS audit_logs(id bigserial PRIMARY KEY,actor text NOT NULL,action text NOT NULL,target text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS model_configuration(id text PRIMARY KEY,payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS sync_metadata(client_id text PRIMARY KEY,last_version bigint,last_sync timestamptz);
